class ScrubbedTaskBoundaryPolicyTest(unittest.TestCase):
    AGENT_INFO = {
        "activity": {
            "commands": [
                "git cat-file -p 2d38362 | head -5",
                "git reflog --all",
            ]
        }
    }
    ATTESTATIONS = [{"source_history_parent": "2d383620e9d1dc5609f1657d1d40a4b247433b03"}]

    def test_unscrubbed_tasks_keep_the_strict_exclusion(self) -> None:
        audit = run.baseline_history_audit(self.AGENT_INFO, self.ATTESTATIONS, {})
        self.assertFalse(audit["ok"])
        self.assertTrue(audit["findings"])

    def test_scrubbed_tasks_record_probing_as_advisory(self) -> None:
        audit = run.baseline_history_audit(
            self.AGENT_INFO, self.ATTESTATIONS, {"scrub_answer_from_history": True}
        )
        self.assertTrue(audit["ok"], "probing an answer-free boundary must not void the row")
        self.assertEqual(audit["findings"], [])
        self.assertTrue(audit["advisory_findings"], "the probing must stay visible in the record")

    def test_clean_rows_are_unchanged_either_way(self) -> None:
        clean = {"activity": {"commands": ["go test ./..."]}}
        for task in ({}, {"scrub_answer_from_history": True}):
            audit = run.baseline_history_audit(clean, self.ATTESTATIONS, task)
            self.assertTrue(audit["ok"])
            self.assertNotIn("advisory_findings", audit)


class StandardCellIsolationTest(unittest.TestCase):
    def test_origin_remote_is_removed(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            root = pathlib.Path(tmp)
            src = root / "src"
            src.mkdir()
        # distribution also carries the FileSet the RecordSet fields source
        # from (cg.TASK_FILE_SET_ID) -- it has no per-file sha256, only the
        # individual FileObjects do.
        shas = {f["sha256"] for f in doc["distribution"] if "sha256" in f}
        self.assertIn("a" * 64, shas)
        self.assertIn("b" * 64, shas)

    def test_distribution_includes_the_task_file_set_the_fields_source_from(self):
        doc = cg.build_croissant(_fixture_manifest(), FIXTURE_DATASHEET)
        file_sets = [f for f in doc["distribution"] if f.get("@type") == "cr:FileSet"]
        self.assertEqual(len(file_sets), 1)
        self.assertEqual(file_sets[0]["@id"], cg.TASK_FILE_SET_ID)
        self.assertTrue(file_sets[0].get("includes"))

    def test_record_set_fields_all_declare_a_source(self):
        doc = cg.build_croissant(_fixture_manifest(), FIXTURE_DATASHEET)
        fields = doc["recordSet"][0]["field"]
        self.assertTrue(fields)
        for field in fields:
            source = field.get("source")
            self.assertIsInstance(source, dict, field)
            self.assertTrue(source.get("fileObject") or source.get("fileSet") or source.get("field"),
                            field)

    def test_file_objects_content_size_is_a_string(self):
        doc = cg.build_croissant(_fixture_manifest(), FIXTURE_DATASHEET)
        file_objects = [f for f in doc["distribution"] if f.get("@type") == "cr:FileObject"]
        self.assertTrue(file_objects)
        for obj in file_objects:
            self.assertIsInstance(obj["contentSize"], str, obj)

    def test_failed_clone_leaves_no_staging_dir_behind(self):
        """A half-clone at the final path would fool the ancestry oracle."""
        with tempfile.TemporaryDirectory() as raw:
            tmp = pathlib.Path(raw)
            cfg = _config(tmp, [])
            cfg["clone"]["host"] = "file:///nonexistent-host-for-tests/"
            dest = tmp / "cache" / "o_repo"
            ok, message = clone_repos.clone_one(cfg, "o/repo", dest)
            self.assertFalse(ok)
            self.assertTrue(message)
            self.assertFalse(dest.exists(), "failed clone left the destination behind")
            self.assertFalse((dest.parent / f"{dest.name}.tmp").exists(),
                             "failed clone left a staging dir behind")


